/*
  FULLSEND Purple Dragon / Sakura - Gamepad Viewer Xbox V2
  Uses the user's supplied controller reference as the actual visual base.
  Canvas: 750 x 630. No external image dependency is required.
*/

html, body {
    background: transparent !important;
    overflow: hidden !important;
}

.controller.xbox.edit {
    width: 750px !important;
    height: 630px !important;
    background-image: url("data:image/png;base64,") !important;
    background-repeat: no-repeat !important;
    background-position: 0 0 !important;
    background-size: 750px 630px !important;
}

/* Keep this custom base for normal/white modes. */
.controller.xbox.edit.white {
    background-image: url("data:image/png;base64,") !important;
}

/* The Xbox/player quadrant from the old GPV skin conflicts with the newer controller layout. */
.xbox.edit .quadrant {
    display: none !important;
}

/* ----- LIVE ANALOG STICKS ----- */
.xbox.edit .sticks {
    width: 371px !important;
    height: 196px !important;
    top: 239px !important;
    left: 144px !important;
    z-index: 20 !important;
}

.xbox.edit .stick {
    width: 64px !important;
    height: 64px !important;
    background-image: url("data:image/png;base64,") !important;
    background-repeat: no-repeat !important;
    background-size: 64px 64px !important;
    background-position: center !important;
    border-radius: 50% !important;
}

.xbox.edit .stick.left {
    left: 10px !important;
    top: 10px !important;
}

.xbox.edit .stick.right {
    left: 298px !important;
    top: 123px !important;
    background-color: transparent !important;
}

.xbox.edit .stick.pressed {
    background-position: center !important;
    filter: brightness(1.18) drop-shadow(0 0 5px rgba(184, 52, 255, .9));
}

/* ----- LIVE ABXY BUTTONS ----- */
.xbox.edit .abxy {
    width: 153px !important;
    height: 156px !important;
    top: 192px !important;
    left: 488px !important;
    z-index: 25 !important;
}

.xbox.edit .button {
    width: 48px !important;
    height: 48px !important;
    background-repeat: no-repeat !important;
    background-size: 48px 48px !important;
    background-position: center !important;
    border-radius: 50% !important;
}

.xbox.edit .button.a { background-image: url("data:image/png;base64,") !important; }
.xbox.edit .button.b { background-image: url("data:image/png;base64,") !important; }
.xbox.edit .button.x { background-image: url("data:image/png;base64,") !important; }
.xbox.edit .button.y { background-image: url("data:image/png;base64,") !important; }

.xbox.edit .button.pressed {
    background-position: center !important;
    margin-top: 5px !important;
    filter: brightness(1.25) drop-shadow(0 0 7px rgba(190, 45, 255, .95));
}

/* ----- D-PAD PRESSED FEEDBACK ----- */
/* Static D-pad is part of the custom base. These elements only add a purple press highlight. */
.xbox.edit .dpad {
    width: 110px !important;
    height: 111px !important;
    top: 345px !important;
    left: 223px !important;
    z-index: 30 !important;
}

.xbox.edit .face {
    background-image: none !important;
    background-color: rgba(184, 42, 255, .50) !important;
    box-shadow: 0 0 8px rgba(184, 42, 255, .65);
    opacity: 0;
}

.xbox.edit .face.pressed {
    opacity: 1 !important;
}

/* ----- VIEW / MENU PRESSED FEEDBACK ----- */
/* Their normal icons are baked into the custom base. */
.xbox.edit .arrows {
    width: 141px !important;
    height: 33px !important;
    top: 264px !important;
    left: 306px !important;
    z-index: 30 !important;
}

.xbox.edit .back,
.xbox.edit .start {
    width: 33px !important;
    height: 33px !important;
    background-image: none !important;
    border-radius: 50% !important;
    background: rgba(184, 42, 255, .36) !important;
    box-shadow: 0 0 9px rgba(184, 42, 255, .8);
    opacity: 0;
}

.xbox.edit .back.pressed,
.xbox.edit .start.pressed {
    opacity: 1 !important;
}

/* ----- ANALOG TRIGGERS ----- */
/* GPV controls trigger opacity from the real analog input. */
.xbox.edit .triggers {
    position: absolute !important;
    width: 446px !important;
    height: 121px !important;
    left: 152px !important;
    top: 0 !important;
    z-index: 40 !important;
    visibility: visible !important;
}

.xbox.edit .trigger {
    width: 88px !important;
    height: 121px !important;
    background-image: linear-gradient(
        to bottom,
        rgba(116, 16, 170, 0) 0%,
        rgba(116, 16, 170, 0) 42%,
        rgba(185, 38, 255, .92) 58%,
        rgba(93, 0, 145, .96) 100%
    ) !important;
    background-position: center !important;
    background-size: 100% 100% !important;
    clip-path: polygon(13% 48%, 87% 48%, 100% 100%, 0% 100%);
    filter: drop-shadow(0 0 7px rgba(183, 39, 255, .8));
}

.xbox.edit .trigger.left {
    float: left !important;
}

.xbox.edit .trigger.right {
    float: right !important;
    transform: rotateY(180deg) !important;
}

/* ----- LB / RB ----- */
.xbox.edit .bumpers {
    position: absolute !important;
    width: 536px !important;
    height: 61px !important;
    left: 107px !important;
    top: 129px !important;
    z-index: 41 !important;
    visibility: visible !important;
}

.xbox.edit .bumper {
    width: 170px !important;
    height: 61px !important;
    background-image: linear-gradient(
        to bottom,
        rgba(190, 45, 255, .78),
        rgba(85, 0, 126, .70)
    ) !important;
    clip-path: polygon(10% 12%, 88% 0%, 100% 72%, 88% 100%, 12% 92%, 0% 55%);
    filter: drop-shadow(0 0 7px rgba(183, 39, 255, .7));
    opacity: 0;
}

.xbox.edit .bumper.pressed {
    opacity: 1 !important;
}

.xbox.edit .bumper.left {
    float: left !important;
}

.xbox.edit .bumper.right {
    float: right !important;
    transform: rotateY(180deg) !important;
}

/* Remove unwanted creator/name pseudo labels if present. */
.controller.xbox.edit::before,
.controller.xbox.edit::after {
    content: none !important;
    display: none !important;
}
